window.__snap = () => {
  const widget = (id) => {
    const root = document.getElementById(id);
    const mine = (selector) => [...root.querySelectorAll(selector)].filter((e) => e.closest('.tabs') === root);
    const tabs = mine('.tab'), panels = mine('.panel'), list = mine('.tab-list')[0];
    return {
      listRole: list ? list.getAttribute('role') : null,
      tabRoles: tabs.map((t) => t.getAttribute('role')),
      selected: tabs.map((t) => t.getAttribute('aria-selected')),
      tabindex: tabs.map((t) => t.getAttribute('tabindex')),
      active: tabs.map((t) => t.classList.contains('active')),
      controls: tabs.map((t) => t.getAttribute('aria-controls') === t.dataset.panel),
      panelRoles: panels.map((p) => p.getAttribute('role')),
      labelledby: panels.map((p) => { const tab = tabs.find((t) => t.dataset.panel === p.id); return Boolean(tab) && p.getAttribute('aria-labelledby') === tab.id; }),
      panelTabindex: panels.map((p) => p.getAttribute('tabindex')),
      hidden: panels.map((p) => p.hasAttribute('hidden')),
      open: panels.map((p) => p.classList.contains('open')),
      shown: panels.map((p) => p.getClientRects().length > 0),
    };
  };
  return { settings: widget('settings'), period: widget('period'), focus: document.activeElement ? document.activeElement.id : null };
}, true
